/** biome-ignore-all lint/style/noRestrictedImports: Node app */

//Ignore specifically from /telemetry from build-core to keep load time fast
import { type Telemetry, type TelemetryEventData, TelemetryFactory } from '@servicenow/sdk-build-core/telemetry'
import * as nodeFs from 'node:fs'
import * as nodePath from 'node:path'

export function createTelemetryClient(sdkDir: string = __dirname, instanceUrl?: URL): Telemetry {
    const hostname = instanceUrl?.hostname

    return TelemetryFactory.create({
        type: 'node',
        attributes: {
            sdkVersion: readSdkVersion(sdkDir),
            clientName: 'cli',
            ...(hostname && { hostname }),
        },
    })
}

function readSdkVersion(sdkDir: string): string {
    const rootDir = findPackageRoot(sdkDir)
    if (!rootDir) {
        return ''
    }
    try {
        const raw = nodeFs.readFileSync(nodePath.join(rootDir, 'package.json'), 'utf-8')
        return (JSON.parse(raw).version as string | undefined) ?? ''
    } catch {
        return ''
    }
}

/**
 * Run `work` with a fresh telemetry client and emit a single event for the run.
 *
 * On success: `work`'s return value controls the emission:
 *   - an object  → sends `{ name: event, data: <returned object> }`
 *   - `void`     → sends `{ name: event }` (name-only event)
 *   - `null`     → emits nothing (use this to opt out of telemetry for the run)
 * On failure: forwards the error to `client.error(event, error, errorData?)` and
 *   re-throws so callers still observe the failure.
 */
export async function withTelemetryEvent<T extends TelemetryEventData | void | null>(
    options: { event: string; sdkDir?: string; instanceUrl?: URL; errorData?: TelemetryEventData },
    work: (client: Telemetry) => Promise<T>
): Promise<T> {
    const client = createTelemetryClient(options.sdkDir, options.instanceUrl)
    try {
        const data = await work(client)
        if (data !== null) {
            client.sendEvent({ name: options.event, ...(data ? { data } : {}) })
        }
        return data
    } catch (error) {
        client.error(options.event, error, options.errorData)
        throw error
    }
}

function findPackageRoot(start: string): string | undefined {
    let dir = nodePath.resolve(start)
    while (true) {
        if (nodeFs.existsSync(nodePath.join(dir, 'package.json'))) {
            return dir
        }
        const parent = nodePath.dirname(dir)
        if (parent === dir) {
            return undefined
        }
        dir = parent
    }
}
